fn shell_game(n: i32, x: i8) -> i8 {
    debug_assert!(n >= 1);
    debug_assert!(x >= 0 && x <= 2);

    // The game repeats every 6 moves (composition of swaps yields a 3-cycle).
    // So we only need n mod 6.
    let k = ((n % 6) + 6) % 6; // handle any unexpected negative n safely

    match (k, x) {
        (0, p) => p,

        (1, 0) => 1,
        (1, 1) => 0,
        (1, 2) => 2,

        (2, 0) => 1,
        (2, 1) => 2,
        (2, 2) => 0,

        (3, 0) => 2,
        (3, 1) => 1,
        (3, 2) => 0,

        (4, 0) => 2,
        (4, 1) => 0,
        (4, 2) => 1,

        (5, 0) => 0,
        (5, 1) => 2,
        (5, 2) => 1,

        _ => x, // unreachable given x in 0..=2 and k in 0..=5
    }
}